package integration_test

import (
	"bytes"
	"context"
	"encoding/binary"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	romcompressor "github.com/olsonb97/romcompressor.go"
	"github.com/olsonb97/romcompressor.go/internal/fileops"
	"github.com/olsonb97/romcompressor.go/internal/process"
)

// Set ROMCOMPRESSOR_CHDMAN to a chdman executable to exercise the real engine.
// Fixtures contain generated bytes, not copyrighted game data.
func TestCHDManRoundTripIntegration(t *testing.T) {
	tool := os.Getenv("ROMCOMPRESSOR_CHDMAN")
	if tool == "" {
		t.Skip("ROMCOMPRESSOR_CHDMAN is not set")
	}
	for _, media := range []string{"dvd", "cd"} {
		t.Run(media, func(t *testing.T) {
			dir := t.TempDir()
			ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
			defer cancel()
			data := make([]byte, 129*2048)
			input := filepath.Join(dir, "source.iso")
			output := filepath.Join(dir, "restored.iso")
			if media == "cd" {
				data = make([]byte, 2352*150)
				input = filepath.Join(dir, "source.cue")
				output = filepath.Join(dir, "restored.cue")
				if err := os.WriteFile(input, []byte("FILE \"source.bin\" BINARY\n  TRACK 01 AUDIO\n    INDEX 01 00:00:00\n"), 0600); err != nil {
					t.Fatal(err)
				}
			}
			for i := range data {
				data[i] = byte((i*17 + i/251) % 256)
			}
			dataInput, dataOutput := input, output
			if media == "cd" {
				dataInput, dataOutput = filepath.Join(dir, "source.bin"), filepath.Join(dir, "restored.bin")
			}
			if err := os.WriteFile(dataInput, data, 0600); err != nil {
				t.Fatal(err)
			}
			compressed := filepath.Join(dir, "game.chd")
			opts := romcompressor.Options{Format: romcompressor.CHD, Media: media, Tools: map[string]string{"chdman": tool}}
			if _, err := romcompressor.Convert(ctx, input, compressed, opts); err != nil {
				t.Fatal(err)
			}
			if info, err := romcompressor.Inspect(ctx, compressed); err != nil || info.Format != romcompressor.CHD || info.Media != media {
				t.Fatalf("inspect generated CHD = %+v, %v; want media %s", info, err, media)
			}
			if media == "dvd" {
				tag := filepath.Join(dir, "dvd-meta.bin")
				if _, err := process.Run(ctx, tool, "dumpmeta", "-i", compressed, "-t", "DVD", "-o", tag); err != nil {
					t.Fatal(err)
				}
				value, err := os.ReadFile(tag)
				if err != nil || !bytes.Equal(value, []byte{0}) {
					t.Fatalf("incorrect DVD metadata: %x, %v", value, err)
				}
			}
			opts.Format = romcompressor.Raw
			if _, err := romcompressor.Convert(ctx, compressed, output, opts); err != nil {
				t.Fatal(err)
			}
			if err := fileops.CompareFiles(ctx, dataInput, dataOutput); err != nil {
				t.Fatal(err)
			}
			if err := romcompressor.Verify(ctx, compressed, opts); err != nil {
				t.Fatal(err)
			}
			chd, err := os.ReadFile(compressed)
			if err != nil {
				t.Fatal(err)
			}
			if len(chd) < 124 || binary.BigEndian.Uint32(chd[12:16]) != 5 {
				t.Fatal("expected chdman to create a v5 CHD")
			}
			chd[84] ^= 1 // Corrupt the overall digest while leaving the raw digest intact.
			badCHD := filepath.Join(dir, "bad.chd")
			if err := os.WriteFile(badCHD, chd, 0600); err != nil {
				t.Fatal(err)
			}
			if err := romcompressor.Verify(ctx, badCHD, opts); err == nil || !strings.Contains(err.Error(), "Overall SHA1") {
				t.Fatalf("expected overall checksum failure, got %v", err)
			}
			badOutput := filepath.Join(dir, "bad"+filepath.Ext(output))
			if _, err := romcompressor.Convert(ctx, badCHD, badOutput, opts); err == nil || !strings.Contains(err.Error(), "Overall SHA1") {
				t.Fatalf("expected extraction to fail at verification, got %v", err)
			}
			if _, err := os.Lstat(badOutput); !os.IsNotExist(err) {
				t.Fatalf("failed extraction published an output: %v", err)
			}
			if media == "cd" {
				cue, err := os.ReadFile(output)
				if err != nil {
					t.Fatal(err)
				}
				if !strings.Contains(string(cue), `"restored.bin"`) {
					t.Fatalf("incorrect extracted CUE: %s", cue)
				}
			}
		})
	}
}

func TestSevenZipRoundTripIntegration(t *testing.T) {
	tool := os.Getenv("ROMCOMPRESSOR_7Z")
	if tool == "" {
		t.Skip("ROMCOMPRESSOR_7Z is not set")
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	dir := t.TempDir()
	for _, compressedInput := range []bool{false, true} {
		name := "game name.gba"
		if compressedInput {
			name = "already compressed.gz"
		}
		t.Run(name, func(t *testing.T) {
			source := filepath.Join(dir, name)
			data := bytes.Repeat([]byte("generated archive fixture\x00\xff"), 8192)
			if err := os.WriteFile(source, data, 0600); err != nil {
				t.Fatal(err)
			}
			if compressedInput {
				raw := filepath.Join(dir, "before-compression.bin")
				if err := os.Rename(source, raw); err != nil {
					t.Fatal(err)
				}
				source = filepath.Join(dir, "wrapped.gz")
				if _, err := romcompressor.Convert(ctx, raw, source, romcompressor.Options{Format: romcompressor.GZIP}); err != nil {
					t.Fatal(err)
				}
			}
			archive := source + ".7z"
			opts := romcompressor.Options{Format: romcompressor.SevenZip, Tools: map[string]string{"7z": tool}}
			if _, err := romcompressor.Convert(ctx, source, archive, opts); err != nil {
				t.Fatal(err)
			}
			listing, err := romcompressor.InspectWithOptions(ctx, archive, opts)
			entries := listing.Entries
			if err != nil {
				t.Fatal(err)
			}
			if len(entries) != 1 || entries[0].Name != filepath.Base(source) {
				t.Fatalf("unexpected archive contents: %+v", entries)
			}
			opts.Format = romcompressor.Raw
			restored := filepath.Join(dir, "restored-"+filepath.Base(source))
			if _, err := romcompressor.Convert(ctx, archive, restored, opts); err != nil {
				t.Fatal(err)
			}
			if err := fileops.CompareFiles(ctx, source, restored); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestSevenZipSelectionIntegration(t *testing.T) {
	tool := os.Getenv("ROMCOMPRESSOR_7Z")
	if tool == "" {
		t.Skip("ROMCOMPRESSOR_7Z is not set")
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	dir := t.TempDir()
	first, second := filepath.Join(dir, "first.bin"), filepath.Join(dir, "nested", "second.bin")
	if err := os.Mkdir(filepath.Dir(second), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(first, []byte("first file"), 0600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(second, []byte("second file"), 0600); err != nil {
		t.Fatal(err)
	}
	archive := filepath.Join(dir, "multiple.7z")
	if _, err := process.Execute(ctx, nil, nil, dir, tool, "a", "-t7z", "-bd", "-y", archive, "--", "first.bin", "nested/second.bin"); err != nil {
		t.Fatal(err)
	}
	output := filepath.Join(dir, "chosen.bin")
	opts := romcompressor.Options{Format: romcompressor.Raw, Tools: map[string]string{"7z": tool}}
	if _, err := romcompressor.Convert(ctx, archive, output, opts); err == nil {
		t.Fatal("chose an entry from an ambiguous archive")
	}
	if _, err := os.Stat(output); !os.IsNotExist(err) {
		t.Fatalf("failed operation published output: %v", err)
	}
	opts.Entry = "nested/second.bin"
	opts.MaxOutput = 1
	if _, err := romcompressor.Convert(ctx, archive, output, opts); err == nil {
		t.Fatal("ignored output limit")
	}
	opts.MaxOutput = 1024
	if _, err := romcompressor.Convert(ctx, archive, output, opts); err != nil {
		t.Fatal(err)
	}
	if err := fileops.CompareFiles(ctx, second, output); err != nil {
		t.Fatal(err)
	}
}

func TestDolphinRoundTripIntegration(t *testing.T) {
	tool := os.Getenv("ROMCOMPRESSOR_DOLPHIN")
	if tool == "" {
		t.Skip("ROMCOMPRESSOR_DOLPHIN is not set")
	}
	dir := t.TempDir()
	source := filepath.Join(dir, "generated.iso")
	data := make([]byte, 2<<20)
	copy(data, "GTEST1")
	binary.BigEndian.PutUint32(data[28:32], 0xc2339f3d)
	copy(data[32:], "Generated compression fixture")
	for i := 65536; i < len(data); i++ {
		data[i] = byte((i*17 + i/251) % 256)
	}
	if err := os.WriteFile(source, data, 0600); err != nil {
		t.Fatal(err)
	}
	for _, format := range []romcompressor.Format{romcompressor.RVZ, romcompressor.WIA, romcompressor.GCZ} {
		t.Run(string(format), func(t *testing.T) {
			ctx := t.Context()
			compressed := filepath.Join(dir, "generated."+string(format))
			opts := romcompressor.Options{Format: format, Tools: map[string]string{"dolphin-tool": tool}}
			if _, err := romcompressor.Convert(ctx, source, compressed, opts); err != nil {
				t.Fatal(err)
			}
			opts.Format = romcompressor.Raw
			restored := compressed + ".iso"
			limited := opts
			limited.MaxOutput = int64(len(data)) - 1
			if err := romcompressor.Verify(ctx, compressed, limited); err == nil {
				t.Fatal("verified a disc over the expanded size limit")
			}
			if _, err := romcompressor.Convert(ctx, compressed, restored, limited); err == nil {
				t.Fatal("restored a disc over the expanded size limit")
			}
			if err := romcompressor.Verify(ctx, compressed, opts); err != nil {
				t.Fatal(err)
			}
			if _, err := romcompressor.Convert(ctx, compressed, restored, opts); err != nil {
				t.Fatal(err)
			}
			if err := fileops.CompareFiles(ctx, source, restored); err != nil {
				t.Fatal(err)
			}
		})
	}
}
